package io.github.chutian0610.jolt.bind;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The generated-binder registry, one home: the facade-level map jolt-gen populates in the
 * forward direction — jolt-bind never depends on jolt-gen (ADR-0004). Consulted before the
 * reflective cache so nested record/POJO values route to generated code when present, and by
 * the direct-read dispatch's capability check ({@code hasDirectRead}). Nothing here is named
 * by generated bytecode — the public doors are {@code Bind.registerGenerated} and
 * {@code Bind.generatedLookupForTest}.
 */
final class GeneratedRegistry {

    private static final Map<Class<?>, TypedBinder<?>> GENERATED = new ConcurrentHashMap<>();

    private GeneratedRegistry() {}

    /** Registers a generated binder for {@code type} (called by jolt-gen only, via Bind). */
    static <T> void register(Class<T> type, TypedBinder<T> binder) {
        GENERATED.put(type, binder);
    }

    /** The registered generated binder for {@code type}, or null (nested routing + dispatch). */
    @SuppressWarnings("unchecked")
    static <T> TypedBinder<T> lookup(Class<T> type) {
        return (TypedBinder<T>) GENERATED.get(type);
    }

    /** Test-visible registered lookup (same map the nested routing consults). */
    static TypedBinder<?> lookupForTest(Class<?> type) {
        return GENERATED.get(type);
    }
}
